from core import *
import warnings
warnings.filterwarnings('ignore',message='X does not have valid feature names')
def main():
 (ROOT/'models').mkdir(exist_ok=True);o=np.load(c.MODEL/'work/final80/oof_predictions.npz');y=o['truth'];groups=o['groups'];fold=o['fold'];x=np.load(c.MODEL/'work/cache_float64/x.npy',mmap_mode='r')[:,FEATURES].astype(np.float32);z=np.load(V9/'train/x.npy',mmap_mode='r');stats=dict(np.load(V9/'preprocess.npz'));outer=fold==0;tr=np.flatnonzero(~outer);val={};metadata={};audit={p.name:c.sha(p) for p in (c.BASE/'data/train').glob('*.txt')};assert len(audit)==80;assert audit==c.load(prior.ROOT/'training_audit.json')['train_sha256']
 for j,t in enumerate(c.TARGETS):
  valid=c.valid(y[:,j],j);cont=valid&~atom(y[:,j],j);target=transform(y[:,j],j);q=quantiles(z,j,stats);meta=calibrate(q,y[:,j],cont);metadata[t]=meta;val[f'{t}_truth']=y[outer,j];val[f'{t}_groups']=groups[outer]
  # Calibration-only crossfit: own-well labels excluded, provider dependencies remain.
  pred={m:np.zeros(len(y)) for m in ['nominal','global','conditional']}
  for f in range(5):
   m=fold==f;cal=calibrate(q,y[:,j],cont&~m)
   for mode in pred:pred[mode][m]=decide(q[m],cal,mode,j)
  for mode,p in pred.items():val[f'{t}_cal_{mode}']=p
  np.save(ROOT/f'oof_q_{t}.npy',q)
  # Strict new-expert outer64/16 check. All difficulty providers exclude outer16.
  inner=np.zeros(len(tr));splits=list(GroupKFold(2).split(tr,groups=groups[tr]))
  for f,(aa,bb) in enumerate(splits):
   fit=tr[aa];fit=fit[cont[fit]];m=fit_save(x[fit],target[fit],None,j,ROOT/'models'/f'{t}_inner64_{f}.txt');inner[bb]=physical(m.predict(x[tr[bb]],num_threads=2),j)
  keep=cont[tr];w=weight(y[tr[keep],j],inner[keep],j)
  for name,ww in [('plain',None),('weighted',w)]:
   fit=tr[keep];m=fit_save(x[fit],target[fit],ww,j,ROOT/'models'/f'{t}_validation_{name}.txt');val[f'{t}_{name}']=physical(m.predict(x[outer],num_threads=2),j)
  # Matched full80 teachers generated by 2-fold well holdout for weight estimation.
  teacher=np.zeros(len(y))
  for f,(aa,bb) in enumerate(GroupKFold(2).split(x,groups=groups)):
   fit=aa[cont[aa]];m=fit_save(x[fit],target[fit],None,j,ROOT/'models'/f'{t}_teacher80_{f}.txt');teacher[bb]=physical(m.predict(x[bb],num_threads=2),j)
  for name,ww in [('plain',None),('weighted',weight(y[cont,j],teacher[cont],j))]:fit_save(x[cont],target[cont],ww,j,ROOT/'models'/f'{t}_{name}.txt')
  print('TARGET_TRAINED',t,'continuous',int(cont.sum()),flush=True)
 c.save(ROOT/'calibration.json',metadata);np.savez_compressed(ROOT/'validation.npz',**val);c.save(ROOT/'training_audit.json',dict(train_sha256=audit,train_wells=80,rows=len(y),outer_train_wells=len(np.unique(groups[~outer])),outer_validation_wells=len(np.unique(groups[outer])),public_truth_loaded=False,atom_labels='Retained in frozen champion decision branch; continuous experts conditional on non-atom, not deleted from task.',weight='0.5+clip(1-scaled_OOF_error/2,0,1), normalized',calibration_validation='Own-fold excluded at calibrator level; legacy provider interdependencies mean not fully nested.',weighted_validation='New continuous experts and difficulty teachers strictly exclude outer16; outer16 development, not final independent test.'));c.save(ROOT/'RUN_STATUS.json',dict(status='trained'));print('TRAIN_COMPLETE',flush=True)
if __name__=='__main__':main()
